css:
.bkck { font-family: "Times New Roman", serif; font-size: 12pt; color: #000; }
.bkck-head { width: 100%; border: none; margin-bottom: 8px; }
.bkck-head td { border: none; vertical-align: top; }
.bkck-title { text-align: center; font-size: 15pt; margin: 10px 0 2px; text-transform: uppercase; }
.bkck-no { text-align: center; margin-bottom: 12px; }
.bkck p { margin: 3px 0; }
.bkck-lines { width: 100%; border-collapse: collapse; margin-top: 8px; }
.bkck-lines th, .bkck-lines td { border: 1px solid #000; padding: 3px 5px; font-size: 11pt; }
.bkck-lines th { background: #f0f0f0; text-align: center; }
.bkck-lines .num { text-align: right; white-space: nowrap; }
.bkck-total td { background: #fafafa; }
.bkck-sign { width: 100%; border: none; margin-top: 24px; }
.bkck-sign td { border: none; height: 90px; vertical-align: top; }
